#include <string>
#include <map>
#include <utility>

// std::map's element type is std::pair<const Key, T>
std::map<std::string, int> m = {{"key", 1}};

// Case 1: Explicit type mismatch creates a temporary
for (const std::pair<std::string, int>& p : m)
{
  // p is a reference to a temporary copy of the map element
  // because p's type is not exactly the element's type
  // (p.first is not const).
}

// Case 2: 'auto' correctly deduces the exact type
for (const auto& p : m)
{
  // p is a reference to the actual element within the map.
  // p's deduced type is const std::pair<const std::string, int>&
  // This is correct and efficient.
}
